import logging
import os
import re
from base64 import b64encode
from typing import Union

from pysnmp.proto import rfc1902

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.http_client import HttpPdu
from taf.hw.pdu.devices.snmp import SnmpPdu
from taf.hw.pdu.exceptions import BadPortNumber, PduConnectionError


class BlackBox(HttpPdu):
    _SET_CODES = {DeviceStatus.ON: 1, DeviceStatus.OFF: 0, DeviceStatus.RESET: "r"}
    _GET_STATUS_OFF = "0"
    _GET_STATUS_ON = "1"
    _GET_STATUS_RESET = "2"
    _HOME_PATH = "config/home_f.html"

    def __init__(self, host: str, username: str, password: str, timeout: Union[float, int], **kwargs):
        self._authorized = False
        auth_string = username + ":" + password
        self._credentials = b64encode(auth_string.encode()).decode()
        self._http_proxy = (
            {"http": kwargs.get("http_proxy")} if kwargs.get("http_proxy") else None
        )
        super(BlackBox, self).__init__(host=host, timeout=timeout)
        self._login()

    def _send_request(self, url, method="GET", headers=None, data=None):
        auth_header = {"Authorization": "Basic " + self._credentials}
        if headers is not None:
            headers.update(auth_header)
        else:
            headers = auth_header
        return super(BlackBox, self)._send_request(
            method=method, url=url, headers=headers, data=data, proxies=self._http_proxy
        )

    def _login(self):
        response = self._send_request(url=self._host, method="GET")
        if not response.ok:
            raise PduConnectionError("Authorization failed.")

    def _build_request_url(self, port, status):
        return os.path.join(self._host, self._HOME_PATH)

    def _parse_response(self, response, port):
        pattern = r"(socket\(" + str(port) + r',"[^"]*",)(\d)'
        return re.search(string=response.content.decode(), pattern=pattern).groups()[1]

    @property
    def _port_setting(self):
        return {
            DeviceStatus.OFF: self._GET_STATUS_OFF,
            DeviceStatus.ON: self._GET_STATUS_ON,
            DeviceStatus.RESET: self._GET_STATUS_RESET,
        }

    def _set_port_status(self, port, status):
        logging.info(f"HTTP: Setting port to {status}: {port}")
        url = os.path.join(self._host, self._HOME_PATH)
        data = [("P" + str(port), self._SET_CODES[status])]
        self._send_request(url=url, method="POST", data=data)

    def reset(self, ports, time_interval=None):
        """
        Reset ports.

        :param ports: List of ports to reset
        :param time_interval: because BlackBox PDU supports reset by its own there is no need to turn the ports
        off and on again manually like the other PDUs so we won't use timeout for this one
        """
        for port in ports:
            self._set_port_status(port, DeviceStatus.RESET)


class BBOXPSE(SnmpPdu):
    """Class provides attributes and private methods to manage BBOXPSE PDU."""

    _KEY = ".1.3.6.1.4.1.24734.15.7.1.1"

    def __init__(self, host, timeout=20, snmp_user=None, community=None):
        """
        :param string host:         IP address or domain name of the BlackBox device.
        :param float timeout:       Maximum number of seconds to wait for expected pdu outlet status.
        :param community:           Community string used by SNMPv1/2
        """
        super(BBOXPSE, self).__init__(host, timeout, snmp_user)

        if not snmp_user:
            self._setup_snmpv1(community)

        self._read_only_partial_oid = self._KEY + ".5.0."
        self._read_write_partial_oid = self._KEY + ".7.0."

    @property
    def _port_setting(self):
        return {DeviceStatus.OFF: "Off", DeviceStatus.ON: "On"}

    def _get_oid_value(self, action, **kwargs):
        values = {DeviceStatus.ON: 0, DeviceStatus.OFF: 1}
        return rfc1902.Integer(values[action])

    def _build_snmp_oid(self, port):
        if port in range(1, 5):
            return f"{self._read_only_partial_oid}{port}"
        else:
            raise BadPortNumber(f"Port number is invalid: {port}")

    def _execute_set_cmd(self, action, snmp_msg, **kwargs):
        snmp_msg_set = f"{self._read_write_partial_oid}{snmp_msg[-1]}"
        SnmpPdu._execute_set_cmd(self, action, snmp_msg_set)

    def _setup_snmpv1(self, community="private"):
        self._community = community
        self._version = 0
